-- Default question banks for the four survey categories. Generated by question_banks.py.
-- Run once after 01_schema.sql. A category that already has sections is left untouched,
-- so this never overwrites edits made in the app.

do $$
declare s uuid;
begin
  if exists (select 1 from public.sections where category_id = 'data-engineering') then return; end if;
end $$;

do $$
