end $$;

do $$
declare s uuid;
begin
  if exists (select 1 from public.sections where category_id = 'architecture') then return; end if;
end $$;

do $$
declare s uuid;
begin
  if exists (select 1 from public.sections where category_id = 'leadership') then return; end if;
end $$;
